const reserveStock = `-- name: ReserveStock :execrows
UPDATE products
SET stock = CASE WHEN stock IS NULL THEN NULL ELSE stock - $1::int END, updated_at = now()
WHERE id = $2 AND (stock IS NULL OR stock >= $1::int)
`

type ReserveStockParams struct {
	Qty int32
	ID  int64
}

// Baris tidak berubah bila stok kurang; jasa (stok NULL) selalu lolos.
func (q *Queries) ReserveStock(ctx context.Context, arg ReserveStockParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, reserveStock, arg.Qty, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

